arguments.new_str:
using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9: Discriminator property renamed to $type — preserve old name for existing documents
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");
        // EF Core 9: id no longer includes discriminator — preserve "Blog|1" format for existing documents
        modelBuilder.Entity<Blog>().HasRootDiscriminatorInJsonId(true);
        // EF Core 9: HasIndex now throws for Cosmos entities — removed (manage indexing via Azure Portal/Bicep)
    }
}

